function hero(topic,title,description){return '<header class="bp2-hero"><span class="bp2-eyebrow">به‌پرور · جلسه دوم · مسیر '+roleName+' · '+topic+'</span><h3>'+title+'</h3><p>'+description+'</p><div class="bp2-kpis"><span>تفویض اختیار</span><span>توانمندسازی</span><span>جانشین‌پروری</span></div></header>';}
