function renderCase(){
 let i=Math.max(0,Math.min(advancedCases.length-1,Number(st.tabs.case||0)));const c=advancedCases[i],choice=st.cases[i],x=c.choices[choice];
 const factOpen=st.caseFacts&&st.caseFacts[i];
 return hero('گفت‌وگوهای کاری','Decision Lab · موقعیت‌های دشوار تفویض','در این شش کیس قرار نیست جواب بدیهی را پیدا کنید؛ باید بین هزینه، ریسک، سرعت و رشد کارکنان قضاوت کنید.')
 +'<p class="bp2-intro">سناریوهای صنعتی، شبیه‌سازی آموزشی‌اند و ادعای ثبت رویداد واقعی شرکت ندارند. تصمیم واقعی باید با ضوابط و اختیارات به‌پرور تطبیق داده شود.</p>'
 +nav(advancedCases.map((x,n)=>'کیس '+(n+1)),'case',i)
 +box(c.title,'<span class="bp2-tag">تعارض تصمیم: '+c.tension+'</span><div class="bp2-story"><p>'+c.setting+'</p></div>'
 +'<div class="bp2-row" style="margin-top:12px">'+btn(factOpen?'پنهان‌کردن داده‌های تکمیلی':'برای تصمیم‌گیری چه اطلاعاتی داریم؟','data-d4-facts="'+i+'"',!!factOpen)+'</div>'
 +(factOpen?'<div class="bp2-facts"><strong>سه واقعیت مؤثر در تصمیم</strong><ul>'+c.facts.map(y=>'<li>'+y+'</li>').join('')+'</ul></div>':'<p class="bp2-small">پیش از انتخاب، مشخص کنید چه فرض‌هایی دارید و کدام واقعیت‌ها هنوز نامعلوم‌اند.</p>')
 +'<h5>از میان اقدام‌های قابل دفاع، کدام را انتخاب می‌کنید؟</h5>'
 +c.choices.map((y,j)=>'<button type="button" class="bp2-btn bp2-choice'+(choice===j?' active':'')+'" data-d3-case="'+i+':'+j+'" aria-pressed="'+(choice===j)+'"><strong>'+String.fromCharCode(65+j)+'.</strong> '+esc(y.name)+'</button>').join('')
 +(x?'<div class="bp2-feedback"><strong>تحلیل Trade-off انتخاب شما؛ نه نمره «درست/غلط»</strong><div class="bp2-grid"><div class="bp2-mini"><strong>مزیت احتمالی</strong>'+x.gain+'</div><div class="bp2-mini"><strong>ریسک / هزینه پنهان</strong>'+x.cost+'</div><div class="bp2-mini"><strong>در چه شرایطی قابل دفاع است؟</strong>'+x.when+'</div><div class="bp2-mini"><strong>گام مکمل</strong>'+x.next+'</div></div></div>':'')
 +'<details><summary>Facilitator Challenge · سؤال دشوارتر</summary><p>'+c.probe+'</p><p><b>نشانه موفقیت در محیط کار:</b> '+c.signal+'</p></details>'
 +textArea('case-'+i,'تصمیم شما برای محیط کار واقعی','چه کسی، چه اختیار محدودی، چه منبعی، چه نقطه کنترل و چه خط قرمزی دارد؟')
 +'<details><summary>Role Play · گفت‌وگوی حرفه‌ای و بازبینی</summary><p>سه نقش: تصمیم‌گیرنده، فرد دریافت‌کننده اختیار و مشاهده‌گر. ۳ دقیقه مذاکره روی اختیار؛ ۲ دقیقه اعلام یک مانع تازه؛ ۲ دقیقه مذاکره مجدد؛ ۱ دقیقه جمع‌بندی.</p><p><b>مشاهده‌گر:</b> آیا مدیر مسئله را روشن کرد؟ آیا حدود تصمیم، مالکیت، منابع و نقطه ارجاع توافق شد؟ آیا جای رشد و یادگیری واقعی باقی ماند؟</p></details>')
 +box('جمع‌بندی منتور',hint('<strong>بهترین پاسخ مطلق وجود ندارد.</strong> تصمیم قوی، تصمیمی است که با آمادگی فرد، فوریت کار، ریسک و سطح اختیار واقعی متناسب باشد. در محیط سازمان، قواعد اجباری همیشه مقدم‌اند.')+'<p class="bp2-small">'+safe+'</p>');
}


