function contractBlock(){
 const fields=[
 ['task','مسئولیت قابل واگذاری',supervisor?'مثلاً تدوین گزارش تحویل شیفتِ مجاز':'مثلاً هماهنگی گزارش پیشرفتِ میان‌واحدی'],
 ['owner','مالک مسئولیت / نفر در حال توسعه','نقش فرد، بدون داده محرمانه'],
 ['outcome','خروجی قابل مشاهده و معیار کیفیت','چه نتیجه‌ای، با چه استانداردی؟'],
 ['limit','حدود اختیار / ممنوعیت‌ها / سقف تصمیم','چه کاری مجاز و چه کاری نیازمند تأیید است؟'],
 ['resources','اطلاعات، ابزار، زمان و حمایت','برای موفقیت چه چیزی لازم است؟'],
 ['checkpoint','زمان پایش و شواهد پیشرفت','کِی و بر اساس چه نشانه‌ای بررسی می‌کنید؟'],
 ['escalate','ریسک و نقطه ارجاع / جایگزین در غیبت','در چه شرایطی توقف و ارجاع لازم است؟']
 ];
 return '<p class="bp2-small">این فرم الگوی آموزشی و محلی است؛ جایگزین مجوز رسمی سازمان نیست.</p>'+fields.map(([key,label,ph])=>'<div class="bp2-q"><label for="bp2-c-'+key+'"><strong>'+label+'</strong></label><textarea data-d3-contract="'+key+'" id="bp2-c-'+key+'" placeholder="'+ph+'">'+esc(st.contract[key]||'')+'</textarea></div>').join('')+hint('قاعده طلایی: «مسئولیت بدون اختیار و منبع، تفویض مؤثر نیست؛ اختیار بدون مرز و پاسخگویی نیز تفویض ایمن نیست.»')+'<div class="bp2-row">'+btn('کپی قرارداد','data-d3-copy="1"')+'</div><p class="bp2-small" id="d3-copy-status" aria-live="polite"></p>';
}

function technique(){
 let i=Math.max(0,Math.min(3,Number(st.tabs.tech||0)));
 let c;
 if(i===0)c=box('پنج سطح اختیار؛ چطور سطح مناسب را انتخاب کنم؟',
 '<p>این «نردبان» برای تصمیم‌های مجاز است؛ سطح بالاتر همیشه بهتر نیست. به سه عامل توجه کنید: <b>آمادگی فرد، ریسک تصمیم و برگشت‌پذیری.</b></p>'
 +'<div class="bp2-grid">'+[
 ['کم‌ریسک + آماده','تصمیم مستقل در مرز مصوب، همراه با گزارش نتیجه'],
 ['کم‌ریسک + در حال یادگیری','تصمیم مشترک یا تأیید اولیه؛ افزایش اختیار بعد از شواهد عملکرد'],
 ['حساس + آماده','تصمیم و تأیید مطابق الزامات رسمی؛ توانمندی فرد، مجوز رسمی نمی‌سازد'],
 ['حساس + در حال یادگیری','مشاهده، تحلیل پیشنهاد و تمرین تحت نظارت؛ نه اجرای مستقل']
 ].map(x=>'<div class="bp2-mini"><strong>'+x[0]+'</strong>'+x[1]+'</div>').join('')+'</div>'
 +'<p class="bp2-small">ماتریس تصمیم‌گیری آموزشی است؛ جایگزین دستورالعمل رسمی فرایند نیست.</p>'
 +levels.map((x,j)=>'<details '+(j===2?'open':'')+'><summary>'+x.title+'</summary><p class="bp2-small" dir="ltr">'+x.eng+'</p><p>'+x.scope+'</p><p><b>چه زمانی منطقی است؟</b> '+x.when+'</p></details>').join('')
 +hint('<b>چالش کلاسی:</b> دو فرد می‌توانند برای یک کار متفاوت، سطح اختیار متفاوت داشته باشند؛ چرا؟')+textArea('level','یک تصمیم خاص، یک فرد مشخص، یک سطح اختیار','کار + سطح فعلی + آمادگی فرد + ریسک + مرز اختیار + شرط ارتقا'));
 if(i===1)c=box('قرارداد هفت‌بندی؛ قبل از واگذاری روی چه چیزی توافق کنیم؟',
 '<p>از این فرم برای یک مسئولیت واقعی و قابل تفویض استفاده کنید. قبل از امضای ذهنی قرارداد، از کارمند بخواهید آن را با زبان خودش بازگو کند؛ اختلاف برداشت در همین مرحله آشکار می‌شود.</p>'+contractBlock()+
 '<details><summary>Red-Team Check · سه نقطه شکست رایج</summary><ol><li>واگذاری هدف بدون دسترسی به داده و منابع؛ فرد مقصرِ شکستِ طراحی می‌شود.</li><li>واگذاری اجرا بدون اختیار تصمیم؛ هر مانع به مدیر برمی‌گردد.</li><li>واگذاری بدون تعریف استثنا؛ فرد در شرایط حساس یا معطل می‌ماند یا از مرز اختیار می‌گذرد.</li></ol></details>');
 if(i===2)c=box('Checkpoint که ریزمدیریت نیست',
 '<p>پیگیری حرفه‌ای فقط پرسیدنِ «به کجا رسید؟» نیست. در هر Checkpoint چهار چیز ثبت شود: <b>شاهد پیشرفت، مانع، حمایت مدیر، تصمیم مرحله بعد.</b></p>'
 +'<div class="bp2-grid">'+[
 ['شواهد نتیجه','چه چیزی قابل مشاهده یا تأیید است؟ نه چندبار به کارمند سر زده‌اید.'],
 ['ریسک تغییر یافته','از آخرین بررسی چه ریسکی اضافه شده یا چه فرضی غلط از آب درآمده؟'],
 ['حمایت مدیر','چه مانعی خارج از اختیار فرد است و مدیر باید رفع کند؟'],
 ['حق تصمیم بعدی','بعد از این تجربه، مرز اختیار باید بیشتر، کمتر یا همان بماند؟']
 ].map(x=>'<div class="bp2-mini"><strong>'+x[0]+'</strong>'+x[1]+'</div>').join('')+'</div>'
 +'<h5>تمرین «کار را پس نمی‌گیرم»</h5><div class="bp2-story"><p>'+(supervisor?'سرگروه می‌گوید «گزارش تحویل خراب شد؛ خودتان تکمیل کنید».':'سرپرست می‌گوید «با این واحد نمی‌شود کار کرد؛ خودتان مداخله کنید».')+'</p></div>'
 +'<p><b>پاسخ حرفه‌ای:</b> «کدام بخش را خودت می‌توانی حل کنی؟ کدام مانع در اختیار من است؟ چه دو گزینه‌ای داریم؟ تا چه زمانی دوباره بررسی می‌کنیم؟»</p>'
 +hint('اگر کیفیت یا ایمنی در خطر است، فوراً مطابق دستورالعمل اقدام کنید؛ استقلال به معنای تأخیر در Escalation نیست.')
 +textArea('check','یک Checkpoint واقعی من','شاهد نتیجه + ریسک + حمایت + اقدام بعدی'));
 if(i===3)c=box('جانشین‌پروری با سنجش آمادگی',
 '<p>جانشین‌پروری یک «فهرست اسامی» نیست. آمادگی باید با شواهد عملکرد زیر نظر مربی و در چارچوب رسمی مشخص شود.</p>'
 +'<div class="bp2-grid">'+[
 ['۱. نقش بحرانی','اگر دو روز فرد اصلی نباشد، چه کاری متوقف می‌شود؟'],
 ['۲. مهارت حیاتی','کدام تصمیم، رابطه کاری، مستند یا صلاحیت برای آن نقش لازم است؟'],
 ['۳. نفر دوم','چه فردی ظرفیت و انگیزه رشد دارد؟ چه شکاف آموزشی دارد؟'],
 ['۴. تجربه محدود','Shadowing، اجرای مشترک، سپس Acting Assignment در محدوده مجاز'],
 ['۵. شواهد آمادگی','نتیجه، کیفیت تصمیم، نیاز به کمک، رعایت حدود و رفتار در فشار'],
 ['۶. پروتکل تداوم','مالک تصمیم جاری، مرجع تأیید، جایگزین و نحوه تحویل دانش']
 ].map(x=>'<div class="bp2-mini"><strong>'+x[0]+'</strong>'+x[1]+'</div>').join('')+'</div>'
 +'<h5>تمرین «دو روز بدون من»</h5><p>پیش از مرخصی فرضی، سه تصمیم خود را بنویسید؛ برای هرکدام مشخص کنید «تصمیم با چه نقشی؟ با چه اختیار مصوب؟ در چه وضعیتی باید ارجاع شود؟»</p>'
 +hint('فردِ مستعد یا جانشین موقت به‌معنای دارا بودن اختیار قانونی یا انتصاب رسمی نیست.')
 +textArea('succession','نقشه جانشین‌پروری در محیط کار','نقش بحرانی + دانش حیاتی + نفر دوم + شواهد آمادگی + آزمون تجربه'));
 return hero('فنون رهبری','جعبه‌ابزار مدیر حرفه‌ای','کاربرگ‌ها برای استفاده در محیط کار طراحی شده‌اند: تصمیم، توافق، پیگیری و ساختن نفر دوم.')
 +nav(techniqueTitles,'tech',i)+c+hint(safe);
}

